    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord[0] < 0 or coord[0] >= self.num_bins:
        return
    if coord[1] < 0 or coord[1] >= self.num_bins:
        return
    self.bins[coord[0]][coord[1]] += weight

