def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    unused_digests = []

    for manifest_file in manifest_files:
        for digest in manifest_file['digests']:
            if digest not in digests_used:
                unused_digests.append(digest)

    for digest in digests_used:
        if digest not in [manifest_file['digests'] for manifest_file in manifest_files]:
            missing_digests.append(digest)

    if missing_digests:
        raise ValueError(f'Missing digests: {missing_digests}')

    if unused_digests:
        raise ValueError(f'Unused digests: {unused_digests}')

    return True

