def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    version_list = version.split(".")
    last_item = version_list[-1]
    last_item_int = int(last_item)
    if last_item_int < 9:
        last_item_int += 1
        version_list[-1] = str(last_item_int)
    else:
        version_list[-1] = "0"
        if len(version_list) == 1:
            version_list.append("1")
        else:
            for i in range(len(version_list)-2, -1, -1):
                if version_list[i] != "9":
                    version_list[i] = str(int(version_list[i]) + 1)
                    break
                else:
                    version_list[i] = "0"
    return ".".join(version_list)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Create an empty dictionary to store the digests for each version
    version_digests = {}
    for version_dir in version_dirs:
        # Get the inventory file for the current version
        inventory_file = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_file):
            raise Exception(f"Inventory file not found for version {version_dir}")
        with open(inventory_file) as f:
            inventory = json.load(f)
        # Extract the content digests from the inventory and store them in the dictionary
        version_digests[version_dir] = {}
        for file in inventory["files"]:
            version_digests[version_dir][file["name"]] = file["digest"]
        # Iterate over the root inventory and check for any missing files or mismatched digests
        root_digests = self.root_inventory["digests"]
        for file in self.root_inventory["files"]:
            if file["name"] not in version_digests[version_dir]:
                raise Exception(f"File {file['name']} missing from version {version_dir} inventory")
            if file["digest"] != version_digests[version_dir][file["name"]]:
                raise Exception(f"File {file['name']} has mismatched digest in version {version_dir} inventory")
    return version_digests

def find_path_type(path):
