    # Check if the file exists
    if not os.path.exists(path):
        return "other - file does not exist"

    # Check if it's an OCFL Storage Root
    if os.path.isdir(path):
        return "root - looks like an OCFL Storage Root"

    # Check if it's an OCFL Object
    if os.path.isfile(path) and not path.endswith(".json"):
        return "object - looks like an OCFL Object"

    # Check if it's an inventory file
    if os.path.isfile(path) and path.endswith(".json"):
        return "file - a file, might be an inventory"

    # Other error
    return "other - " + path

