def size_to_bytes(size: str) -> int:
    multiplier = 1
    size = size.strip().upper()
    if size.endswith("KB"):
        multiplier = 1000
    elif size.endswith("MB"):
        multiplier = 1000000
    elif size.endswith("GB"):
        multiplier = 1000000000
    try:
        return int(float(size[:-2]) * multiplier)
    except ValueError:
        return int(size)

