    if not os.path.exists(archive_path):
        raise ValueError("The archive path you provided does not exist.")

    if not filename:
        filename = os.path.basename(archive_path)

    if not os.path.exists(tmp_path):
        raise ValueError("The temporary path you provided does not exist.")

    with tempfile.NamedTemporaryFile() as temp_file:
        archive_filename = os.path.basename(archive_path)
        temp_file_name = temp_file.name
        try:
            shutil.unpack_archive(archive_filename, temp_file_name, filename)
        except (shutil.ReadError, shutil.FormatError):
            raise ValueError("The archive could not be unpacked.")
        else:
            repo_path = os.path.join(temp_file_name, archive_filename)
            return repo_path

