        make_value = lambda bin_: bin_.content
    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.left
    elif get_coordinate == "right":
        get_coordinate = lambda bin_.right
    elif get_coordinate == "middle":
        get_coordinate = lambda bin_: (bin_.left + bin_.right) / 2
    else:
        raise ValueError("Invalid value for 'get_coordinate': %s" % get_coordinate)

    if field_names is None:
        field_names = ("x", "y")
    if len(field_names) != 2:
        raise ValueError("'field_names' must have exactly two elements")

    if scale is None:
        scale = hist.scale

    x = []
    y = []
    for bin_ in hist.bins:
        x.append(get_coordinate(bin_))
        y.append(make_value(bin_))

    return Graph(x, y, scale=scale, field_names=field_names)

